<template>
  <div class="time-container">

    <!-- Строка: дата | время | день недели -->
    <div class="time-row">
      <div class="time-date">{{ dateString }}</div>
      <div class="time-sep"></div>
      <div class="time-clock">
        {{ hours }}:{{ minutes }}:<span class="time-seconds">{{ seconds }}</span>
      </div>
      <div class="time-sep"></div>
      <div class="time-day" :style="{ color: isWorkday ? 'orange' : '#16a34a' }">{{ dateStringDay }}</div>
    </div>

    <!-- Таймлайн рабочего дня (только пн–пт) -->
    <div class="wd-tl" v-if="isWorkday">
      <div class="wd-track-row">

        <!-- Трек с заливкой -->
        <div class="wd-track-bg">
          <div class="wd-track-fill" :style="{ width: workPct + '%' }"></div>
          <!-- Обед 12:00–13:00: 37.5%–50% от рабочего дня -->
          <div class="wd-lunch-seg"></div>
        </div>

        <!-- Веха 09:00 -->
        <div class="wd-ms" style="left: 0%">
          <div class="wd-ms-dot"></div>
          <span class="wd-ms-lbl" style="margin-top: 3px">09:00</span>
        </div>

        <!-- Веха 12:00 — начало обеда -->
        <div class="wd-ms wd-ms--lunch" style="left: 37.5%">
          <div class="wd-ms-dot wd-ms-dot--lunch"></div>
          <span class="wd-ms-lbl" style="margin-top: 3px">12:00</span>
        </div>

        <!-- Веха 13:00 — конец обеда -->
        <div class="wd-ms wd-ms--lunch" style="left: 50%">
          <div class="wd-ms-dot wd-ms-dot--lunch"></div>
          <span class="wd-ms-lbl" style="margin-top: 3px">13:00</span>
        </div>

        <!-- Веха 17:00 -->
        <div class="wd-ms" style="left: 100%">
          <div class="wd-ms-dot"></div>
          <span class="wd-ms-lbl" style="margin-top: 3px">17:00</span>
        </div>

        <!-- Пульсирующая точка «сейчас» -->
        <div class="wd-now" :style="{ left: workPct + '%' }"></div>

      </div>
    </div>

  </div>
</template>

<script>
export default {
  name: 'TimeComponent',

  data() {
    return {
      seconds:       '',
      minutes:       '',
      hours:         '',
      dateString:    '',
      dateStringDay: '',
      isWorkday:     false,
      workPct:       0,
      timer:         null,
    }
  },

  mounted() {
    this.updateTime()
    this.timer = setInterval(this.updateTime, 1000)
  },

  beforeUnmount() {
    if (this.timer) clearInterval(this.timer)
  },

  watch: {
    '$i18n.locale'() {
      this.updateTime()
    },
  },

  methods: {
    updateTime() {
      const now = new Date()

      this.seconds = String(now.getSeconds()).padStart(2, '0')
      this.minutes = String(now.getMinutes()).padStart(2, '0')
      this.hours   = String(now.getHours()).padStart(2, '0')

      // Дата и день недели через i18n (реагирует на смену языка)
      const days   = this.$tm('time.days')
      const months = this.$tm('time.months')

      this.dateString    = `${now.getDate()} ${months[now.getMonth()]} ${now.getFullYear()}`
      this.dateStringDay = days[now.getDay()]

      // Прогресс рабочего дня: пн=1 … пт=5
      const dow = now.getDay()
      this.isWorkday = dow >= 1 && dow <= 5

      if (this.isWorkday) {
        // 9:00–17:00 = 480 минут
        const elapsed = (now.getHours() - 9) * 60 + now.getMinutes() + now.getSeconds() / 60
        this.workPct = Math.max(0, Math.min(100, (elapsed / 480) * 100))
      }
    },
  },
}
</script>

